  const [location] = useLocation();
  const [modeOpen, setModeOpen] = useState(false);
  const [mode, setMode] = useState<"founder" | "learner">(() => {
    if (typeof window === "undefined") return "founder";
    return window.localStorage.getItem("asaasi-view-mode") === "learner" ? "learner" : "founder";
  });
  useEffect(() => {
    if (location.startsWith("/dashboard/learner")) setMode("learner");
    else if (location === "/dashboard") setMode("founder");
  }, [location]);
  useEffect(() => { window.localStorage.setItem("asaasi-view-mode", mode); }, [mode]);
  return <aside className="workspace-sidebar">
    <div className="workspace-profile"><div className="avatar avatar-yellow">SA</div><div><strong>Sara Ammar</strong><span>{t("Founder · Cairo", "مؤسسة · القاهرة")}</span></div><button type="button" className="icon-button mobile-only" onClick={onClose} aria-label={t("Close workspace menu", "إغلاق قائمة مساحة العمل")}><X size={16} /></button></div>
    <div className="mode-switcher"><span className="mono">{t("Active view", "العرض النشط")}</span><button type="button" className="mode-switcher-current" aria-expanded={modeOpen} aria-haspopup="true" onClick={() => setModeOpen((value) => !value)}>{mode === "learner" ? <BookOpen size={15} /> : <BriefcaseBusiness size={15} />} {mode === "learner" ? t("Learner view", "عرض المتعلم") : t("Founder workspace", "مساحة المؤسس")} <ChevronRight size={14} style={{ transform: modeOpen ? "rotate(90deg)" : undefined, transition: "transform 160ms" }} /></button>{modeOpen && <div className="mode-switcher-menu" role="menu"><Link href="/dashboard" role="menuitem" className={mode === "founder" ? "mode-switcher-option is-active" : "mode-switcher-option"} onClick={() => { setModeOpen(false); onClose?.(); }}><BriefcaseBusiness size={14} /> {t("Founder workspace", "مساحة المؤسس")} {mode === "founder" && <Check size={14} />}</Link><Link href="/dashboard/learner" role="menuitem" className={mode === "learner" ? "mode-switcher-option is-active" : "mode-switcher-option"} onClick={() => { setModeOpen(false); onClose?.(); }}><BookOpen size={14} /> {t("Learner view", "عرض المتعلم")} {mode === "learner" && <Check size={14} />}</Link></div>}<p>{t("Switch modes without losing your place.", "بدل المساحات دون أن تفقد مكانك.")}</p></div>
    <nav className="workspace-nav" aria-label={t("Workspace navigation", "تنقل مساحة العمل")}>{(mode === "learner" ? learnerLinks : dashboardLinks).map(([href, label, Icon]) => { const isActive = location === href || (href !== "/dashboard" && location.startsWith(href)); const labels: Record<string, string> = { Home: t("Home", "الرئيسية"), "Learning path": t("Learning path", "مسار التعلم"), "AI coach": t("AI coach", "مساعد الذكاء الاصطناعي"), "Find people": t("Find people", "ابحث عن أشخاص"), Network: t("Network", "شبكتك"), Community: t("Community", "المجتمع"), Professionals: t("Professionals", "المتخصصون"), Events: t("Events", "الفعاليات"), "My events": t("My events", "فعالياتي"), Requests: t("Requests", "الطلبات"), Invitations: t("Invitations", "الدعوات"), Membership: t("Membership", "العضوية"), "Membership perks": t("Membership perks", "مزايا العضوية"), Saved: t("Saved", "المحفوظات"), Following: t("Following", "المتابَعون"), Activity: t("Activity", "النشاط"), Organizations: t("Organizations", "المنظمات"), "My profile": t("My profile", "ملفي الشخصي"), Settings: t("Settings", "الإعدادات") }; return <Link key={href} href={href} onClick={onClose} className={isActive ? "active" : ""} aria-current={isActive ? "page" : undefined}><Icon size={16} /><span>{labels[label] ?? label}</span>{label === "Saved" && <small aria-label={t("3 saved items", "٣ عناصر محفوظة")}>3</small>}</Link>; })}</nav>
    <div className="sidebar-brief"><SectionLabel>{t("Next signal", "الإشارة التالية")}</SectionLabel><strong>{t("Review your pricing brief", "راجع ملخص التسعير")}</strong><p>{t("12 min · based on your founder stage.", "١٢ دقيقة · وفق مرحلة مؤسستك.")}</p><Link href="/tools/pricing-advisor">{t("Open tool", "فتح الأداة")} <ArrowRight size={13} /></Link></div>
  </aside>;
