export function ProductShell({ children, title, active }: { children: ReactNode; title?: string; active?: string }) {
  const { t } = useLocale();
  const { isAuthed } = useAuth();
  const [menu, setMenu] = useState(false);
  const [location, setLocation] = useLocation();
  useEffect(() => {
    const isAuthRoute = location === "/login" || location === "/signup" || location === "/forgot-password" || location === "/reset-password" || location === "/verify-email";
    if (!isAuthed && !isAuthRoute) {
      window.sessionStorage.setItem("asaasi-return-route", location);
      setLocation("/login");
    }
  }, [isAuthed, location, setLocation]);
  useEffect(() => { if (title) document.title = `${title} · ASaaSI`; return () => { document.title = "ASaaSI · MENA SaaS Founder Community"; }; }, [title]);
  if (!isAuthed) return <main className="empty-state" style={{ margin: "80px auto", maxWidth: 420 }} aria-busy="true" aria-live="polite"><LockKeyhole size={20} aria-hidden="true" /><h2>{t("Sign in required.", "تسجيل الدخول مطلوب.")}</h2><p role="status">{t("Taking you to login...", "جار نقلك إلى تسجيل الدخول...")}</p></main>;
  return <div className="product-shell"><div className="product-mobile-menu"><button type="button" className="button button-ghost" aria-expanded={menu} aria-controls="workspace-sidebar" onClick={() => setMenu(!menu)}><Menu size={16} /> {menu ? t("Close workspace", "إغلاق مساحة العمل") : t("Open workspace", "فتح مساحة العمل")}</button></div><div className="product-shell-grid">{menu && <button type="button" className="product-sidebar-overlay" aria-label={t("Close workspace navigation", "إغلاق تنقل مساحة العمل")} onClick={() => setMenu(false)} />}<div id="workspace-sidebar" className={menu ? "workspace-sidebar-wrap open" : "workspace-sidebar-wrap"}><WorkspaceSidebar active={active} onClose={() => setMenu(false)} /></div><main id="main-content" data-workspace-route={active} className="product-main">{location === "/dashboard/weekly-review" && <WeeklyFollowThroughScan />}{children}</main></div></div>;
}

function WeeklyFollowThroughScan() {
  const { t, isRTL } = useLocale();
  const records = getWorkflowRecords();
  const conversations = records.filter((record) => record.kind === "introduction" && (record.status === "introduced" || (record.status === "completed" && !record.outcomeCheckCompletedAt)));
  const eventSignals = records.filter((record) => record.kind === "event" && Boolean(record.eventOutcomeAt));
  const items = [...conversations, ...eventSignals].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 3);
  if (!items.length) return null;
  const detail = (record: (typeof records)[number]) => {
    if (record.kind === "introduction" && record.status === "introduced") return { label: t("Conversation waiting", "محادثة بانتظار التوثيق"), copy: t("Reflect the first conversation while its useful detail is still specific.", "وثّق المحادثة الأولى بينما لا تزال تفاصيلها المفيدة محددة.") };
    if (record.kind === "introduction") return { label: t("Outcome check", "فحص النتيجة"), copy: record.outcomeCheckDue ? t(`Name what changed by ${record.outcomeCheckDue}.`, `سمِ ما الذي تغيّر بحلول ${record.outcomeCheckDue}.`) : t("Name what changed after this connection.", "سمِ ما الذي تغيّر بعد هذا الربط.") };
    return { label: t("Event signal", "إشارة فعالية"), copy: record.eventOutcomeNote || t("Bring the signal into the next decision review.", "انقل الإشارة إلى مراجعة القرار التالية.") };
  };
  return <section className="weekly-follow-through-scan"><div><SectionLabel>{t("Follow-through scan", "فحص المتابعة")}</SectionLabel><h2>{t("Keep the conversations that can change the week in view.", "أبقِ المحادثات التي يمكن أن تغيّر الأسبوع في نطاق الرؤية.")}</h2><p>{t("These are not more bets. They are pending people, outcomes, or signals that can sharpen the decision already in motion.", "هذه ليست رهانات إضافية. إنها أشخاص أو نتائج أو إشارات معلقة يمكنها صقل القرار الجاري بالفعل.")}</p></div><div>{items.map((record) => { const item = detail(record); return <article key={record.id}><span>{item.label}</span><strong>{t(record.title, record.titleAr)}</strong><p>{item.copy}</p><Link href={record.href} className="text-link">{t("Open follow-through", "افتح المتابعة")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></article>; })}</div><Link href="/dashboard/registrations" className="button button-light">{t("Open Activity", "افتح النشاط")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></section>;
}

function FounderBriefChecklist() {
  const { t, formatNum } = useLocale();
  const [complete, setComplete] = useState<boolean[]>(() => {
    if (typeof window === "undefined") return [true, false, false];
    const saved = window.localStorage.getItem("asaasi-founder-brief");
    return saved ? JSON.parse(saved) : [true, false, false];
  });
  useEffect(() => { window.localStorage.setItem("asaasi-founder-brief", JSON.stringify(complete)); }, [complete]);
  const steps = [
    { label: t("Define your signal", "حدد إشارتك"), detail: t("Profile and founder context", "الملف الشخصي وسياق المؤسس"), href: "/dashboard/profile" },
    { label: t("Choose one move", "اختر خطوة واحدة"), detail: t("People, requests, or an event", "أشخاص أو طلبات أو فعالية"), href: "/matching" },
    { label: t("Make the next move", "اتخذ الخطوة التالية"), detail: t("Create a focused request", "أنشئ طلبا مركزا"), href: "/requests/new" },
  ];
  const completed = complete.filter(Boolean).length;
  return <section className="founder-brief-persisted" aria-labelledby="founder-brief-persisted-title"><div className="founder-brief-copy"><span className="mono">{t("Persistent founder brief", "ملخص المؤسس المستمر")}</span><h2 id="founder-brief-persisted-title">{t("Keep the next move visible.", "أبقِ الخطوة التالية واضحة.")}</h2><p>{t(`${completed} of 3 signals are complete. This checklist follows your account, not a single session.`, `اكتملت ${formatNum(completed)} من ٣ إشارات. تتبع هذه القائمة حسابك، لا جلسة واحدة.`)}</p></div><ol>{steps.map((step, index) => <li key={step.href} className={complete[index] ? "is-complete" : ""}><button type="button" className="brief-check" aria-pressed={complete[index]} aria-label={t(`Mark ${step.label} complete`, `وضع ${step.label} كمكتمل`)} onClick={() => setComplete((current) => current.map((value, itemIndex) => itemIndex === index ? !value : value))}>{complete[index] ? <Check size={14} /> : <span>{String(index + 1).padStart(2, "0")}</span>}</button><div><strong>{step.label}</strong><small>{step.detail}</small></div><Link href={step.href} className="text-link">{t("Open", "فتح")} <ArrowRight size={13} /></Link></li>)}</ol></section>;
}

