  const nextStepOutcomes = completedIntroductionOutcomes.filter((record) => record.introductionOutcome === "next-step").length;
  const usefulLearningOutcomes = completedIntroductionOutcomes.filter((record) => record.introductionOutcome === "useful-learning").length;
  const pausedMatchCount = Object.keys(recommendationFeedback).length;
  const feedbackReasonCounts = Object.values(recommendationFeedback).reduce((counts, entry) => ({ ...counts, [entry.reason]: (counts[entry.reason] ?? 0) + 1 }), {} as Record<string, number>);
  const leadingFeedbackReason = Object.entries(feedbackReasonCounts).sort((a, b) => b[1] - a[1])[0]?.[0];
  const outcomeTimeline = records.filter((record) => (record.kind === "decision" && Boolean(record.outcome || record.weeklyReflection)) || (record.kind === "introduction" && Boolean(record.introductionOutcome || record.introductionReflection)) || (record.kind === "event" && Boolean(record.eventOutcomeAt))).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 4);
  const currentWeekStart = getWeekStart();
