  const weeklyOutcomeLabel = latestWeeklyOutcome?.outcome === "keep" ? t("Keep", "استمر") : latestWeeklyOutcome?.outcome === "change" ? t("Change", "غيّر") : latestWeeklyOutcome?.outcome === "stop" ? t("Stop", "أوقف") : t("No completed outcome this week", "لا توجد نتيجة مكتملة هذا الأسبوع");
  const briefRecovery = activeResearchCadence && weeklyPrimaryRecord
