  const savedEvent = records.find((record) => record.kind === "event");
  const application = records.find((record) => record.kind === "application");
  const upcoming = events.find((event) => event.href === savedEvent?.href) ?? events[0];
  const calendarKey = `asaasi-event-calendar-${upcoming.slug}`;
