  useEffect(() => { window.localStorage.setItem(calendarKey, String(calendarAdded)); }, [calendarAdded, calendarKey]);
  useEffect(() => { window.localStorage.setItem(reminderKey, String(reminderSet)); }, [reminderSet, reminderKey]);
