    q1: ["Where is the retention signal appearing first?", "أين تظهر إشارة الاحتفاظ أولا؟"], q1Hint: ["Choose the earliest observable customer behavior.", "اختر سلوك العميل الأقدم القابل للملاحظة."], options1: [["Activation is incomplete", "التفعيل غير مكتمل"], ["Usage falls after the first month", "الاستخدام ينخفض بعد الشهر الأول"], ["A key feature is not adopted", "ميزة رئيسية لا تُعتمد"], ["Renewal conversations start too late", "محادثات التجديد تبدأ متأخرة"]],
    q2: ["Which intervention can you test with one cohort?", "أي تدخل يمكنك اختباره مع مجموعة واحدة؟"], q2Hint: ["Pick an intervention that produces a visible response, not a broad retention programme.", "اختر تدخلا ينتج استجابة مرئية لا برنامجا واسعا للاحتفاظ."], options2: [["A guided activation check-in", "متابعة تفعيل موجهة"], ["A use-case review", "مراجعة حالة الاستخدام"], ["A targeted feature prompt", "توجيه ميزة مستهدف"], ["An earlier renewal conversation", "محادثة تجديد أبكر"]],
